 void home(){permissionStatus=null;permissionButton=null;visibleAlarm=null;actions=null;if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(false);setTurnScreenOn(false);}getWindow().clearFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);base();label("СОЗДАНИЕ СТРУКТУРЫ",22);label("Напоминания о встречах",28);partner=field("Имя партнёра");guests=field("Гости (по одному на строку)");date=Calendar.getInstance();date.add(Calendar.HOUR,7);time=label(fmt(date.getTimeInMillis(),"dd.MM.yyyy HH:mm"),30);button("Выбрать дату и время",()->new DatePickerDialog(this,(v,y,m,d)->{date.set(y,m,d);new TimePickerDialog(this,(w,h,min)->{date.set(Calendar.HOUR_OF_DAY,h);date.set(Calendar.MINUTE,min);date.set(Calendar.SECOND,0);time.setText(fmt(date.getTimeInMillis(),"dd.MM.yyyy HH:mm"));},date.get(Calendar.HOUR_OF_DAY),date.get(Calendar.MINUTE),true).show();},date.get(Calendar.YEAR),date.get(Calendar.MONTH),date.get(Calendar.DAY_OF_MONTH)).show());permissionPanel();button("Сохранить встречу",()->schedule());button("Предпросмотр наставника",()->showAlarm(data(2,date.getTimeInMillis(),900).putExtra("mentor",true)));button("Предпросмотр запроса подтверждения",()->showAlarm(data(2,date.getTimeInMillis(),901).putExtra("mentor",true).putExtra("approval",true)));button("Тест: два коротких через 10 секунд",()->test(6));button("Тест: три коротких через 10 секунд",()->test(2));refreshPermissions();}
 Intent data(int stage,long meeting,int id){return new Intent(this,AlarmReceiver.class).putExtra("stage",stage).putExtra("meeting",meeting).putExtra("partner",partner.getText().toString()).putExtra("guests",guests.getText().toString()).putExtra("id",id);}
